"comparison": {
"performance": {
"monolith": {
"advantages": "进程内方法调用与共享内存，通信延迟极低；本地事务执行效率高，无分布式网络开销与序列化损耗。",
"disadvantages": "单模块高负载或内存泄漏可能拖慢整个进程；资源争抢严重，无法针对特定计算/IO密集型功能做针对性硬件优化。"
},
"microservices": {
"advantages": "可根据各服务的资源消耗特征（如CPU/GPU/高IO）独立配置底层硬件或缓存策略，瓶颈隔离性强。",
"disadvantages": "跨服务RPC/REST网络通信带来额外I/O与序列化延迟；分布式事务与跨服务数据聚合复杂且显著降低整体吞吐。"
}
},
"maintenance_cost": {
"monolith": {
